def _rows(official: list[tuple[int, int, float]]) -> list[dict]:
    """Official rows, plus estimated rows below them: a straight line from band 1 (raw 0) to band 4, half-rounded."""
    lowest = official[-1][0]
    rows = [{"min_raw": lo, "max_raw": hi, "band": b} for lo, hi, b in official]
    for raw in range(lowest - 1, -1, -1):
        band = max(1.0, math.floor(8 * raw / lowest + 0.5) / 2)
        rows.append({"min_raw": raw, "max_raw": raw, "band": band, "estimated": True})
    return rows


